import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt) public {
        // Bound to admissible values that fit address balance mechanics
        depositAmt = bound(depositAmt, 0, type(uint128).max);
        withdrawAmt = bound(withdrawAmt, 0, type(uint64).max);

        // Fund the contract by sending ETH from a non-owner
        address donor = address(0xdead);
        vm.deal(donor, depositAmt);
        vm.prank(donor);
        (bool s,) = address(c).call{value: depositAmt}("");
        require(s);

        uint256 balanceBefore = address(c).balance;
        require(balanceBefore >= withdrawAmt);

        // Owner withdraws: Owner is the deployer of c (msg.sender of setUp -> this contract)
        vm.prank(address(this));
        try c.withdraw{value: withdrawAmt}() { } catch { }

        uint256 balanceAfter = address(c).balance;
        // The invariant: after a successful withdraw by owner, the contract balance
        // MUST have decreased. The mutant transfers 0, leaving balance unchanged.
        assertTrue(balanceAfter < balanceBefore);
    }
}

