pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 sendAmount, address actor) public {
        // Restrict domain: initialBalance must fit within reasonable gas/transfer limits and
        // sendAmount must be at least initialBalance to enter the if-branch of multiplicate.
        vm.assume(initialBalance <= type(uint128).max);
        vm.assume(sendAmount >= initialBalance);
        // Actor must not be Owner so we can call Command as Owner.
        vm.assume(actor != c.Owner());

        // Fund the contract with initialBalance.
        vm.deal(address(c), initialBalance);

        // Prepare call data for multiplicate(actor) via Command.
        bytes memory data = abi.encodeWithSelector(c.multiplicate.selector, actor);

        // Perform the call as Owner.
        vm.prank(c.Owner());
        try c.Command{value: sendAmount}(address(c), data) {
            // Success indicates transfer was allowed.
            // The invariant: after a successful multiplicate via Command,
            // the contract balance must be 0 (all funds transferred to actor).
            assertEq(address(c).balance, 0);
        } catch {
            // If it reverted, the contract balance must remain unchanged (initialBalance).
            // This covers the case where the buggy require fails but the reference would succeed.
            assertEq(address(c).balance, initialBalance);
        }
    }
}

